{
  "summary": "Lire et utiliser le fichier 'table.json' pour extraire les données des lots et calculer les valeurs de concentration finale, masse totale et volume total.",
  "actions": [
    {
      "tool": "read_artifact",
      "name": "table.json"
    },
    {
      "tool": "construct_table",
      "name": "mix_table.json",
      "schema": {
        "batches": {
          "concentration": "INTEGER",
          "concentration_unit": "TEXT",
          "lot": "TEXT",
          "volume": "INTEGER",
          "volume_unit": "TEXT"
        }
      },
      "sql": "SELECT concentration, concentration_unit, volume, volume_unit FROM batches"
    },
    {
      "tool": "run_table",
      "name": "mix_table.json",
      "input": {
        "dataset": "reservoir"
      }
    },
    {
      "tool": "construct_table",
      "name": "conversion_table.json",
      "schema": {
        "conversion": {
          "from_unit": "TEXT",
          "to_unit": "TEXT",
          "factor": "FLOAT"
        }
      },
      "sql": "SELECT 'g/L' AS from_unit, 'mg/L' AS to_unit, 1000 AS factor UNION SELECT 'ug/mL', 'mg/L', 0.001"
    },
    {
      "tool": "run_table",
      "name": "conversion_table.json",
      "input": {
        "dataset": "reservoir"
      }
    }
  ],
  "done": false
}
